/* ---------- [KD] الشريط السفلي يلتصق بأسفل الشاشة الظاهرة: يقيس الفرق بين أسفل الشريط وأسفل الشاشة الظاهرة (visualViewport) ويزيحه به عبر --kBb ---------- */
(function(){
  var vv=window.visualViewport,m=document.querySelector('.mobMn'),root=document.documentElement;
  if(!vv||!m) return;
  var g=0,raf=0;
  function fix(){
    raf=0;
    if(vv.scale>1.01||getComputedStyle(m).display==='none') return;
    var bottom=m.getBoundingClientRect().bottom-g;
    var ng=Math.round(vv.offsetTop+vv.height-bottom);
    if(Math.abs(ng)<2) ng=0;
    if(ng>200||ng<-200) ng=0;
    if(ng!==g){ g=ng; root.style.setProperty('--kBb',g+'px'); }
  }
  function later(){ if(!raf) raf=requestAnimationFrame(fix); }
  vv.addEventListener('resize',later); vv.addEventListener('scroll',later);
  window.addEventListener('scroll',later,{passive:true}); window.addEventListener('resize',later);
  window.addEventListener('touchend',function(){setTimeout(later,350)},{passive:true});
  later();
})();

/* ================= [KD] الشريط السفلي في الهاتف: يلتصق بأسفل الشاشة الظاهرة دائما (JS: kBb). بعض المتصفحات تبقي العناصر الثابتة على ارتفاع الشاشة القديم حين يختفي شريط العنوان أثناء التمرير ================= */
.mobMn,.toTopB,.toTopF{translate:0 var(--kBb,0px)}

/* ================= [KD] الشريط السفلي في الهاتف: حل CSS فقط بلا جافاسكريبت
   1) لا overflow على html: كان overflow-x:hidden على html يجعل بعض متصفحات الهاتف تحسب العناصر الثابتة من ارتفاع الشاشة القديم حين يختفي شريط العنوان فيرتفع الشريط
      ومنع التمرير الأفقي صار على .mainWrp بالقيمة clip التي لا تؤثر في العناصر الثابتة ولا في sticky
   2) امتداد بلون الشريط تحته: إن تأخر متصفح لحظة في إنزال الشريط أثناء التمرير لا يظهر تحته فراغ من الصفحة
   3) هامش أسفل الشريط بقدر شريط الإيماءات في iPhone ================= */
.mainWrp{overflow-x:clip}
.mobMn{padding-bottom:env(safe-area-inset-bottom,0px)}
.mobMn::before{content:'';position:absolute;top:100%;left:-1px;right:-1px;height:160px;background:inherit;pointer-events:none}
